/**
 * @description: User Portal Navbar (mirrors institute_portal Sidebar pattern)
 * @author: Institute User Portal
 * @date: 2026
 */
import React, { useContext } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { FaUniversity, FaUserGraduate, FaUserTie, FaBus } from 'react-icons/fa';
import { RiDashboardFill } from 'react-icons/ri';
import { MdLogout } from 'react-icons/md';
import { AuthContext } from '../../App';
import { isExactMatch } from '../../services/commonUtills/FormValidations';

const getActiveNavModule = (pathname) => {
  if (!pathname || pathname === '/' || pathname.startsWith('/dashboard')) {
    return 'dashboard';
  }
  if (pathname.startsWith('/profile')) {
    return 'profile';
  }
  return null;
};

function NavbarUser() {
  const { stateAuth, dispatchAuth } = useContext(AuthContext);
  const location = useLocation();
  const navigate = useNavigate();
  const activeModule = getActiveNavModule(location.pathname);

  if (!stateAuth?.user) return null;

  const userType = (stateAuth.user.typ || '').toUpperCase();
  const codes = stateAuth.user.cds || '';

  const logout = () => {
    dispatchAuth({ type: 'LOGOUT' });
    navigate('/');
  };

  const brandName =
    userType === 'STUDENT'
      ? 'Student Portal'
      : userType === 'TRANSPORT'
      ? 'Transport Portal'
      : 'Staff Portal';

  const roleIcon =
    userType === 'STUDENT' ? (
      <FaUserGraduate />
    ) : userType === 'TRANSPORT' ? (
      <FaBus />
    ) : (
      <FaUserTie />
    );

  return (
    <>
      <aside className="user-nav-sidebar">
        {/* Branding header */}
        <div className="user-nav-brand">
          <div className="user-nav-brand-icon">{roleIcon}</div>
          <div className="user-nav-brand-text">
            <h4>{brandName}</h4>
            <span>{stateAuth.user.emlid}</span>
          </div>
        </div>

        {/* Nav Links */}
        <div className="user-nav-menu-wrapper">
          <ul className="user-nav-menu-list">
            {/* Home / Dashboard */}
            {isExactMatch(codes, 'D_H_B') && (
              <li
                className={`user-nav-menu-item ${
                  activeModule === 'dashboard' ? 'active' : ''
                }`}
              >
                <a href="/#" onClick={(e) => { e.preventDefault(); navigate('/dashboard'); }} className="user-nav-menu-link">
                  <RiDashboardFill className="menu-icon" />
                  <span>Home</span>
                </a>
              </li>
            )}

            {/* Role section title */}
            <div className="user-nav-section">
              <span className="user-nav-section-title">MY ACCOUNT</span>
              {isExactMatch(codes, 'S_F') && userType === 'STAFF' && (
                <li className={`user-nav-menu-item ${activeModule === 'profile' ? 'active' : ''}`}>
                  <a href="/#" onClick={(e) => { e.preventDefault(); navigate('/profile'); }} className="user-nav-menu-link">
                    <FaUserTie className="menu-icon" />
                    <span>My Profile</span>
                  </a>
                </li>
              )}
              {userType === 'STUDENT' && (
                <li className={`user-nav-menu-item ${activeModule === 'profile' ? 'active' : ''}`}>
                  <a href="/#" onClick={(e) => { e.preventDefault(); navigate('/profile'); }} className="user-nav-menu-link">
                    <FaUserGraduate className="menu-icon" />
                    <span>My Profile</span>
                  </a>
                </li>
              )}
              {userType === 'TRANSPORT' && (
                <li className={`user-nav-menu-item ${activeModule === 'profile' ? 'active' : ''}`}>
                  <a href="/#" onClick={(e) => { e.preventDefault(); navigate('/profile'); }} className="user-nav-menu-link">
                    <FaBus className="menu-icon" />
                    <span>My Profile</span>
                  </a>
                </li>
              )}
            </div>
          </ul>
        </div>

        {/* Logout */}
        <div className="user-nav-footer">
          <div className="user-nav-support-card" onClick={logout}>
            <div className="user-nav-support-icon">
              <MdLogout size={16} />
            </div>
            <div className="user-nav-support-text">
              <h5>Logout</h5>
              <span>End Session</span>
            </div>
          </div>
        </div>
      </aside>
    </>
  );
}

export default NavbarUser;
